impl TerminalContext { # [doc = " Creates a new `TerminalContext` from parallel vectors of command data."] # [doc = ""] # [doc = " All three slices must have the same length; entries at the same index"] # [doc = " are combined into a single [`TerminalCommand`].  If the lengths differ,"] # [doc = " the shortest slice determines how many entries are produced."] pub fn new (commands : Vec < String > , exit_codes : Vec < i32 > , timestamps : Vec < u64 >) -> Self { let entries = commands . into_iter () . zip (exit_codes) . zip (timestamps) . map (| ((command , exit_code) , timestamp) | TerminalCommand { command , exit_code , timestamp , }) . collect () ; Self { commands : entries } } # [doc = " Returns `true` if there are no recorded commands."] pub fn is_empty (& self) -> bool { self . commands . is_empty () } }